CREATE TABLE agent_anchor (id integer, anchored_at timestamp not null, directory varchar(1000) not null, session_id varchar(128) not null unique, status varchar(32) not null check ((status in ('stale','active'))), title varchar(500) not null, updated_at timestamp not null, primary key (id));
CREATE TABLE agent_pause (id integer, duration_ms bigint, pause_start timestamp not null, procedure_id bigint not null, reason varchar(32) check ((reason in ('session_gone','user_cancel','pause_failed'))), resume_at timestamp, session_id varchar(128) not null, status varchar(32) not null check ((status in ('paused','expired','aborted','resumed'))), primary key (id));
CREATE TABLE download_event (id integer, agent_id varchar(128) not null, destination varchar(1000) not null, idempotency_key varchar(128) not null unique, item varchar(1000) not null, item_type varchar(128) not null, occurred_at timestamp not null, procedure_id bigint, record_type varchar(32) not null check ((record_type in ('download','hallucination','graph_usage','upload','failure','token_economy','source','errors','quality'))), redacted boolean not null, result varchar(16) not null check ((result in ('success','failure'))), session_id varchar(128), size_bytes bigint not null, source varchar(1000) not null, write_source varchar(32) not null check ((write_source in ('rest','event_service','mcp'))), primary key (id));
CREATE TABLE error_detail (id integer, agent_id varchar(128) not null, code varchar(64) not null, failure_event_id bigint not null, failure_type varchar(32) not null check ((failure_type in ('db_write_failure','network_error','hallucination','wrong_data','logic_error','timeout','unknown','build_failure','permission_error','scope_error','deploy_failure','test_failure','tool_error'))), field_or_resource varchar(255), message varchar(2000) not null, occurred_at timestamp not null, severity varchar(16) not null check ((severity in ('high','critical','low','medium'))), primary key (id));
CREATE TABLE failure_event (id integer, agent_id varchar(128) not null, failure_type varchar(32) not null check ((failure_type in ('db_write_failure','network_error','hallucination','wrong_data','logic_error','timeout','unknown','build_failure','permission_error','scope_error','deploy_failure','test_failure','tool_error'))), idempotency_key varchar(128) not null unique, occurred_at timestamp not null, procedure_id bigint, record_type varchar(32) not null check ((record_type in ('download','hallucination','graph_usage','upload','failure','token_economy','source','errors','quality'))), session_id varchar(128), severity varchar(16) not null check ((severity in ('high','critical','low','medium'))), write_source varchar(32) not null check ((write_source in ('rest','event_service','mcp'))), primary key (id));
CREATE TABLE graph_usage_event (id integer, agent_id varchar(128) not null, consulted_before_work boolean not null, distinct_nodes integer not null, idempotency_key varchar(128) not null unique, occurred_at timestamp not null, procedure_id bigint, query_count integer not null, record_type varchar(32) not null check ((record_type in ('download','hallucination','graph_usage','upload','failure','token_economy','source','errors','quality'))), session_id varchar(128), write_source varchar(32) not null check ((write_source in ('rest','event_service','mcp'))), primary key (id));
CREATE TABLE hallucination_event (id integer, agent_id varchar(128) not null, idempotency_key varchar(128) not null unique, occurred_at timestamp not null, procedure_id bigint, record_type varchar(32) not null check ((record_type in ('download','hallucination','graph_usage','upload','failure','token_economy','source','errors','quality'))), response_ref varchar(500) not null, session_id varchar(128), write_source varchar(32) not null check ((write_source in ('rest','event_service','mcp'))), primary key (id));
CREATE TABLE procedure (id integer, created_at timestamp not null, directory varchar(1000) not null, ended_at timestamp, session_id varchar(128) not null unique, started_at timestamp not null, status varchar(32) not null check ((status in ('aborted','active','completed'))), title varchar(500) not null, updated_at timestamp not null, primary key (id));
CREATE TABLE quality_evaluation (id integer, adherence_level integer not null check ((adherence_level<=4) and (adherence_level>=0)), agent_id varchar(128) not null, artifact_level integer not null check ((artifact_level<=4) and (artifact_level>=0)), authority varchar(16) not null check ((authority in ('OWNER','SELF'))), evidence_level integer not null check ((evidence_level<=4) and (evidence_level>=0)), honesty_level integer not null check ((honesty_level<=4) and (honesty_level>=0)), idempotency_key varchar(128) not null unique, occurred_at timestamp not null, procedure_id bigint, process_level integer not null check ((process_level<=4) and (process_level>=0)), rationale varchar(4000) not null, score integer not null check ((score>=0) and (score<=10)), session_id varchar(128), write_source varchar(32) not null check ((write_source in ('rest','event_service','mcp'))), primary key (id));
CREATE TABLE settings (id integer, key varchar(128) not null unique, max_value varchar(255), min_value varchar(255), owner varchar(32) not null check ((owner in ('agent','user'))), updated_at timestamp not null, updated_by varchar(128) not null, value varchar(2000) not null, value_type varchar(32) not null check ((value_type in ('string','integer','enum','url'))), primary key (id));
CREATE TABLE source_event (id integer, agent_id varchar(128) not null, cited boolean, idempotency_key varchar(128) not null unique, occurred_at timestamp not null, origin varchar(32) not null check ((origin in ('domain','corpus','graph'))), procedure_id bigint, purpose varchar(1000) not null, record_type varchar(32) not null check ((record_type in ('download','hallucination','graph_usage','upload','failure','token_economy','source','errors','quality'))), redacted boolean not null, result varchar(16) not null check ((result in ('success','failure'))), session_id varchar(128), source varchar(1000) not null, task_context varchar(1000) not null, write_source varchar(32) not null check ((write_source in ('rest','event_service','mcp'))), primary key (id));
CREATE TABLE token_economy_event (id integer, agent_id varchar(128) not null, baseline_input_tokens bigint, baseline_output_tokens bigint, idempotency_key varchar(128) not null unique, input_tokens bigint not null, measurable boolean not null, model_id varchar(128) not null, not_measurable_reason varchar(500), occurred_at timestamp not null, output_tokens bigint not null, procedure_id bigint, record_type varchar(32) not null check ((record_type in ('download','hallucination','graph_usage','upload','failure','token_economy','source','errors','quality'))), savings_tokens bigint, session_id varchar(128), write_source varchar(32) not null check ((write_source in ('rest','event_service','mcp'))), primary key (id));
CREATE TABLE upload_event (id integer, agent_id varchar(128) not null, destination varchar(1000) not null, idempotency_key varchar(128) not null unique, item varchar(1000) not null, item_type varchar(128) not null, occurred_at timestamp not null, procedure_id bigint, record_type varchar(32) not null check ((record_type in ('download','hallucination','graph_usage','upload','failure','token_economy','source','errors','quality'))), redacted boolean not null, result varchar(16) not null check ((result in ('success','failure'))), sent boolean not null, session_id varchar(128), size_bytes bigint not null, write_source varchar(32) not null check ((write_source in ('rest','event_service','mcp'))), primary key (id));
CREATE TABLE work_session (id integer, active_ms bigint not null, ended_at timestamp, mode varchar(32) not null check ((mode in ('stopwatch','project_stopwatch'))), override_at timestamp, override_author varchar(128), paused_ms bigint not null, procedure_id bigint, started_at timestamp not null, target_seconds integer, timezone varchar(64) not null, total_ms bigint not null, primary key (id));
